def _get_db(folder: str):
    """Get a FeaturesDatabase instance for a folder."""
    if not folder:
        return None
    db_path = FeaturesDatabase.default_db_path(folder)
    if not db_path.exists():
        return None
    return FeaturesDatabase(db_path)


